SELECT * FROM (SELECT dept_name, CASE WHEN budget >= 4182000 THEN 'high' WHEN budget >= 1637000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN dept_name = 'HR' THEN 1 ELSE 0 END) AS hr_count FROM departments GROUP BY dept_name, CASE WHEN budget >= 4182000 THEN 'high' WHEN budget >= 1637000 THEN 'mid' ELSE 'low' END) AS agg WHERE hr_count >= 25 ORDER BY dept_name DESC, budget_bucket
